+    assert_eq!(original.kind, ToolKind::Laser);
+    let data = project::tool_to_json(&original);
+    assert_eq!(data["kind"], "laser", "{data}");
+    assert_eq!(project::tool_from_json(&data).expect("reads back"), original);
