+fn fixture() -> Value {
+    json!({
+        "general": { "model": "Laser test", "kind": "laser" },
+        "kinematics": { "default": {
+            "units": { "length": "mm", "angle": "degrees" },
+            "parts": [
+                { "id": "x", "name": "X", "type": "linear", "travel": { "min": 0.0, "max": 400.0 } },
+                { "id": "y", "name": "Y", "type": "linear", "travel": { "min": 0.0, "max": 300.0 } },
+                { "id": "beam", "name": "laser head", "type": "head" }
